script:
frappe.ui.form.on('Item', {
    setup(frm) {
        frm.set_query('custom_building', () => ({
            filters: {
                item_group: 'building',
                has_variants: 1,
                disabled: 0
            }
        }));
    }
});

frappe.ui.form.on('Subscription Plan', {
    setup(frm) {
        // عرض المباني التي لها وحدات فقط
        frm.set_query('custom_building', () => {
            return {
                filters: {
                    has_variants: 1,
                    disabled: 0
                }
            };
        });

        // عرض وحدات المبنى المختار فقط
        frm.set_query('item', () => {
            if (!frm.doc.custom_building) {
                return {
                    filters: {
                        name: ['=', '']
                    }
                };
            }

            return {
                filters: {
                    variant_of: frm.doc.custom_building,
                    has_variants: 0,
                    disabled: 0
                }
            };
        });
    },

    custom_building(frm) {
        // مسح الوحدة عند تغيير المبنى
        frm.set_value('item', '');
    }
});

frappe.ui.form.on('Subscription Plan', {
    item(frm) {
        if (frm.is_new()) {
            return frm.set_value(
                'plan_name',
                frm.doc.item || ''
            );
        }
    }
});

frappe.ui.form.on('Subscription Plan', {
    custom_building(frm) {
        return frm.set_value(
            'custom_building_board',
            frm.doc.custom_building || ''
        );
    },

    before_save(frm) {
        return frm.set_value(
            'custom_building_board',
            frm.doc.custom_building || ''
        );
    }
});

frappe.ui.form.on('Subscription', {
    refresh(frm) {
        if (frm.is_new() || frm.doc.docstatus === 2) return;

        frm.add_custom_button('قيود العقد', () => {
            frappe.set_route('List', 'Journal Entry', {
                custom_residential_lease: frm.doc.name
            });
        }, 'التأمين');

        if (frm.doc.status === 'Cancelled') return;

        frm.add_custom_button('تحصيل التأمين', async () => {
            if (frm.is_dirty()) {
                frappe.throw('احفظ تعديلات العقد أولًا.');
            }

            if (
                frm.doc.party_type !== 'Customer' ||
                !frm.doc.party ||
                !frm.doc.company
            ) {
                frappe.throw('حدد المستأجر والشركة في العقد.');
            }

            const required = flt(
                frm.doc.custom_required_security_deposit
            );

            const currency = frm.doc.custom_settlement_currency;
            const depositAccount =
                '2130 - Refundable Security Deposits - O';

            if (required <= 0 || !currency) {
                frappe.throw(
                    'حدد مبلغ التأمين المطلوب وعملة التسوية، ثم احفظ.'
                );
            }

            const accountResult = await frappe.db.get_value(
                'Account',
                depositAccount,
                [
                    'company',
                    'account_currency',
                    'is_group',
                    'disabled',
                    'root_type'
                ]
            );

            const deposit = accountResult.message;

            if (
                !deposit ||
                deposit.company !== frm.doc.company ||
                deposit.account_currency !== currency ||
                deposit.is_group ||
                deposit.disabled ||
                deposit.root_type !== 'Liability'
            ) {
                frappe.throw(
                    'راجع شركة حساب التأمين وعملته وإعداداته.'
                );
            }

            const companyResult = await frappe.db.get_value(
                'Company',
                frm.doc.company,
                'default_currency'
            );

            if (companyResult.message.default_currency !== currency) {
                frappe.throw(
                    'هذا الزر يدعم حاليًا عملة الشركة نفسها فقط.'
                );
            }
            const summaryResponse = await frappe.call({
    method: 'get_lease_deposit_summary',
    args: { lease: frm.doc.name }
});

const summary = summaryResponse.message;

if (!summary) {
    frappe.throw('تعذر قراءة ملخص التأمين.');
}

const available = flt(summary.available_for_new);

if (available <= 0) {
    frappe.msgprint(
        'التأمين المطلوب مغطى بقيود محفوظة، بما فيها المسودات. ' +
        'راجع التأمين ← قيود العقد.'
    );
    return;
}
            const dialog = new frappe.ui.Dialog({
                title: 'تحصيل تأمين مسترد',
                fields: [
                    {
                        fieldname: 'currency',
                        label: 'العملة',
                        fieldtype: 'Link',
                        options: 'Currency',
                        default: currency,
                        read_only: 1
                    },
                    {
                        fieldname: 'amount',
                        label: 'مبلغ التأمين المراد تحصيله',
                        fieldtype: 'Currency',
                        options: 'currency',
                        default: required,
                        reqd: 1
                    },
                    {
                        fieldname: 'cash_account',
                        label: 'حساب البنك أو الصندوق',
                        fieldtype: 'Link',
                        options: 'Account',
                        reqd: 1,
                        get_query() {
                            return {
                                filters: {
                                    company: frm.doc.company,
                                    is_group: 0,
                                    disabled: 0,
                                    account_currency: currency,
                                    account_type: ['in', ['Bank', 'Cash']]
                                }
                            };
                        }
                    },
                    {
                        fieldname: 'posting_date',
                        label: 'تاريخ التحصيل',
                        fieldtype: 'Date',
                        default: frappe.datetime.get_today(),
                        reqd: 1
                    },
                    {
                        fieldname: 'reference_no',
                        label: 'رقم مرجع التحويل أو الإيصال',
                        fieldtype: 'Data'
                    }
                ],
                primary_action_label: 'فتح مسودة القيد',
                async primary_action(values) {
                    const amount = flt(values.amount);

                    if (amount <= 0 || amount > available) {
                        frappe.throw(
                            'المبلغ يجب أن يكون أكبر من صفر ولا يتجاوز المتاح: ' +
                            available
                         );
                    }

                    const result = await frappe.db.get_value(
                        'Account',
                        values.cash_account,
                        [
                            'account_type',
                            'company',
                            'account_currency',
                            'is_group',
                            'disabled'
                        ]
                    );

                    const cash = result.message;

                    if (
                        !cash ||
                        cash.company !== frm.doc.company ||
                        cash.account_currency !== currency ||
                        !['Bank', 'Cash'].includes(cash.account_type) ||
                        cash.is_group ||
                        cash.disabled
                    ) {
                        frappe.throw('اختر حساب بنك أو صندوق صالحًا.');
                    }

                    if (
                        cash.account_type === 'Bank' &&
                        !values.reference_no
                    ) {
                        frappe.throw('أدخل رقم مرجع التحويل البنكي.');
                    }

                    dialog.hide();

                    frappe.new_doc('Journal Entry', {
                        company: frm.doc.company,
                        voucher_type:
                            cash.account_type === 'Bank'
                                ? 'Bank Entry'
                                : 'Cash Entry',
                        custom_residential_lease: frm.doc.name,
                        custom_tenant: frm.doc.party
                    }, entry => {
                        entry.posting_date = values.posting_date;
                        entry.user_remark =
                            'تحصيل تأمين مسترد للعقد ' + frm.doc.name;

                        if (values.reference_no) {
                            entry.cheque_no = values.reference_no;
                            entry.cheque_date = values.posting_date;
                        }

                        entry.accounts = [];

                        const debit = frappe.model.add_child(
                            entry, 'accounts'
                        );
                        debit.account = values.cash_account;
                        debit.account_currency = currency;
                        debit.exchange_rate = 1;
                        debit.debit_in_account_currency = amount;
                        debit.credit_in_account_currency = 0;

                        const credit = frappe.model.add_child(
                            entry, 'accounts'
                        );
                        credit.account = depositAccount;
                        credit.account_currency = currency;
                        credit.exchange_rate = 1;
                        credit.debit_in_account_currency = 0;
                        credit.credit_in_account_currency = amount;
                    });
                }
            });

            dialog.show();
        }, 'التأمين');
    }
});

frappe.ui.form.on('Subscription', {
    setup(frm) {
        frm.set_query('plan', 'plans', (doc, cdt, cdn) => {
            if (!doc.start_date || !doc.end_date) {
                frappe.throw('حدد تاريخ بداية العقد ونهايته أولًا.');
            }

            const signature = lease_availability_signature(frm);

            if (frm.__available_plans_signature !== signature) {
                frappe.throw(
                    'لم تكتمل مراجعة الوحدات المتاحة. ' +
                    'انتظر قليلًا أو اضغط تحديث الوحدات المتاحة.'
                );
            }

            const selectedElsewhere = (doc.plans || [])
                .filter(row => row.name !== cdn && row.plan)
                .map(row => row.plan);

            const available = (frm.__available_lease_plans || [])
                .filter(name => !selectedElsewhere.includes(name));

            return {
                filters: {
                    name: [
                        'in',
                        available.length
                            ? available
                            : ['__NO_AVAILABLE_LEASE_PLAN__']
                    ]
                }
            };
        });
    },

    refresh(frm) {
        frm.add_custom_button(
            'تحديث الوحدات المتاحة',
            () => load_available_lease_plans(frm)
        );

        return load_available_lease_plans(frm);
    },

    start_date(frm) {
        return load_available_lease_plans(frm);
    },

    end_date(frm) {
        return load_available_lease_plans(frm);
    }
});

function lease_availability_signature(frm) {
    return JSON.stringify([
        frm.doc.start_date || '',
        frm.doc.end_date || '',
        frm.is_new() ? '' : frm.doc.name
    ]);
}

async function load_available_lease_plans(frm) {
    const requestId = (frm.__availability_request || 0) + 1;
    frm.__availability_request = requestId;

    frm.__available_lease_plans = [];
    frm.__available_plans_signature = null;

    if (!frm.doc.start_date || !frm.doc.end_date) return;

    if (frm.doc.end_date < frm.doc.start_date) {
        frappe.msgprint('نهاية العقد يجب ألا تسبق بدايته.');
        return;
    }

    const signature = lease_availability_signature(frm);

    try {
        const response = await frappe.call({
            method: 'get_available_lease_plans',
            args: {
                start_date: frm.doc.start_date,
                end_date: frm.doc.end_date,
                current_lease: frm.is_new() ? '' : frm.doc.name
            }
        });

        if (frm.__availability_request !== requestId) return;
        if (lease_availability_signature(frm) !== signature) return;

        const data = response.message;

        if (!data || !Array.isArray(data.plans)) {
            throw new Error('Invalid availability response');
        }

        frm.__available_lease_plans = data.plans;
        frm.__available_plans_signature = signature;

    } catch (error) {
        if (frm.__availability_request !== requestId) return;

        frm.__available_lease_plans = [];
        frm.__available_plans_signature = null;

        frappe.msgprint(
            'تعذر تحميل الوحدات المتاحة. راجع رسالة الخطأ ثم أعد المحاولة.'
        );
    }
}

frappe.ui.form.on('Payment Entry', {
    refresh(frm) {
        return fill_lease_tenant(frm);
    },

    custom_residential_lease(frm) {
        return fill_lease_tenant(frm);
    }
});

async function fill_lease_tenant(frm) {
    if (
        frm.doc.docstatus !== 0 ||
        !frm.doc.custom_residential_lease ||
        frm.doc.party ||
        frm.__loading_lease_tenant
    ) return;

    frm.__loading_lease_tenant = true;

    try {
        const lease_name = frm.doc.custom_residential_lease;

        const result = await frappe.db.get_value(
            'Subscription',
            lease_name,
            ['party_type', 'party', 'company']
        );

        const lease = result.message;

        // Ignore a response if the selected lease changed.
        if (frm.doc.custom_residential_lease !== lease_name) return;

        if (!lease || !lease.party) {
            frappe.throw('لم يتم تحديد المستأجر في العقد.');
        }

        if (lease.party_type !== 'Customer') {
            frappe.throw('العقد المحدد يجب أن يكون مرتبطًا بعميل.');
        }

        if (lease.company !== frm.doc.company) {
            frappe.throw('شركة سند القبض لا تطابق شركة العقد.');
        }

        await frm.set_value('party_type', 'Customer');
        await frm.set_value('party', lease.party);

    } finally {
        frm.__loading_lease_tenant = false;
    }
}

frappe.ui.form.on('Subscription', {
    refresh(frm) {
        if (frm.is_new() || frm.doc.docstatus === 2) return;

        frm.add_custom_button('سندات قبض العقد', async () => {
    if (frm.is_dirty()) {
        frappe.throw('احفظ تعديلات العقد أولًا.');
    }

    const response = await frappe.call({
        method: 'get_lease_payment_entries',
        args: {
            lease: frm.doc.name
        },
        freeze: true,
        freeze_message: 'جارٍ تحميل سندات قبض العقد...'
    });

    const names = response.message;

    if (!Array.isArray(names)) {
        frappe.throw('تعذر تحميل سندات القبض.');
    }

    if (!names.length) {
        frappe.msgprint(
            'لا توجد سندات قبض مرتبطة بالعقد أو بفواتيره.'
        );
        return;
    }

    frappe.route_options = {
        name: ['in', names],
        payment_type: 'Receive',
        docstatus: ['!=', 2]
    };

    frappe.set_route('List', 'Payment Entry');
}, 'التحصيل');

        if (frm.doc.status === 'Cancelled') return;

        frm.add_custom_button('تحصيل دفعة مقدمة', async () => {
            if (frm.is_dirty()) {
                frappe.throw('احفظ تعديلات العقد أولًا.');
            }

            if (
                frm.doc.party_type !== 'Customer' ||
                !frm.doc.party ||
                !frm.doc.company
            ) {
                frappe.throw('حدد المستأجر والشركة أولًا.');
            }

            const agreed = flt(frm.doc.custom_agreed_rent_advance);
            const currency = frm.doc.custom_settlement_currency;

            if (agreed <= 0 || !currency) {
                frappe.throw(
                    'أدخل عملة التسوية والدفعة المقدمة المتفق عليها، ثم احفظ العقد.'
                );
            }

            // Include drafts so reopening the button does not
            // suggest collecting an amount already in a draft.
            const payments = await frappe.db.get_list('Payment Entry', {
                filters: {
                    custom_residential_lease: frm.doc.name,
                    custom_lease_payment_purpose: 'Rent Advance',
                    payment_type: 'Receive',
                    docstatus: ['!=', 2]
                },
                fields: [
                    'name',
                    'paid_amount',
                    'paid_from_account_currency'
                ],
                limit_page_length: 1000
            });

            let recorded = 0;

            for (const payment of payments) {
                if (payment.paid_from_account_currency !== currency) {
                    frappe.throw(
                        'يوجد سند دفعة مقدمة بعملة مختلفة. راجع سندات العقد قبل المتابعة.'
                    );
                }
                recorded += flt(payment.paid_amount);
            }

            const remaining = flt(agreed - recorded, 2);

            if (remaining <= 0) {
                frappe.msgprint(
                    'المبلغ المتفق عليه مغطى بسندات محفوظة، بما فيها المسودات. راجع سندات قبض العقد.'
                );
                return;
            }

            const dialog = new frappe.ui.Dialog({
                title: 'تحصيل دفعة مقدمة',
                fields: [
                    {
                        fieldname: 'currency',
                        label: 'العملة',
                        fieldtype: 'Link',
                        options: 'Currency',
                        default: currency,
                        read_only: 1
                    },
                    {
                        fieldname: 'amount',
                        label: 'المبلغ المراد تحصيله',
                        fieldtype: 'Currency',
                        options: 'currency',
                        default: remaining,
                        reqd: 1
                    }
                ],
                primary_action_label: 'فتح مسودة سند قبض',
                primary_action(values) {
                    const amount = flt(values.amount);

                    if (amount <= 0 || amount > remaining) {
                        frappe.throw(
                            'أدخل مبلغًا أكبر من صفر ولا يتجاوز المتبقي: ' +
                            remaining
                        );
                    }

                    dialog.hide();

                    frappe.new_doc('Payment Entry', {
                        payment_type: 'Receive',
                        company: frm.doc.company,
                        party_type: 'Customer',
                        party: frm.doc.party,
                        custom_residential_lease: frm.doc.name,
                        custom_lease_payment_purpose: 'Rent Advance'
                    }, payment => {
                        payment.posting_date = frappe.datetime.get_today();
                        payment.paid_amount = amount;
                        payment.received_amount = amount;
                    });
                }
            });

            dialog.show();
        }, 'التحصيل');
    }
});

frappe.ui.form.on('Subscription', {
    refresh(frm) {
        if (frm.is_new()) return;

        frm.add_custom_button('رد التأمين', async () => {
            if (frm.is_dirty()) {
                frappe.throw('احفظ تعديلات العقد أولًا.');
            }

            if (
                frm.doc.party_type !== 'Customer' ||
                !frm.doc.party ||
                !frm.doc.company
            ) {
                frappe.throw('راجع المستأجر والشركة في العقد.');
            }

            const response = await frappe.call({
                method: 'get_lease_deposit_summary',
                args: { lease: frm.doc.name }
            });

            const summary = response.message;

            if (!summary) {
                frappe.throw('تعذر قراءة رصيد التأمين.');
            }

            const available = flt(summary.available_refund);
            const currency = summary.currency;
            const depositAccount =
                '2130 - Refundable Security Deposits - O';

            if (available <= 0) {
                frappe.msgprint(
                    'لا يوجد رصيد متاح للرد. راجع قيود العقد والمسودات.'
                );
                return;
            }

            const companyResult = await frappe.db.get_value(
                'Company',
                frm.doc.company,
                'default_currency'
            );

            if (companyResult.message.default_currency !== currency) {
                frappe.throw(
                    'المسار الحالي يدعم عملة الشركة نفسها فقط.'
                );
            }

            const dialog = new frappe.ui.Dialog({
                title: 'رد تأمين للمستأجر',
                fields: [
                    {
                        fieldname: 'currency',
                        label: 'العملة',
                        fieldtype: 'Link',
                        options: 'Currency',
                        default: currency,
                        read_only: 1
                    },
                    {
                        fieldname: 'amount',
                        label: 'المبلغ المراد رده',
                        fieldtype: 'Currency',
                        options: 'currency',
                        default: available,
                        reqd: 1
                    },
                    {
                        fieldname: 'cash_account',
                        label: 'حساب البنك أو الصندوق الذي سيصرف المبلغ',
                        fieldtype: 'Link',
                        options: 'Account',
                        reqd: 1,
                        get_query() {
                            return {
                                filters: {
                                    company: frm.doc.company,
                                    is_group: 0,
                                    disabled: 0,
                                    account_currency: currency,
                                    account_type: ['in', ['Bank', 'Cash']]
                                }
                            };
                        }
                    },
                    {
                        fieldname: 'posting_date',
                        label: 'تاريخ الرد',
                        fieldtype: 'Date',
                        default: frappe.datetime.get_today(),
                        reqd: 1
                    },
                    {
                        fieldname: 'reason',
                        label: 'سبب الرد',
                        fieldtype: 'Small Text',
                        reqd: 1
                    },
                    {
                        fieldname: 'reference_no',
                        label: 'رقم مرجع التحويل أو الإيصال',
                        fieldtype: 'Data'
                    }
                ],
                primary_action_label: 'فتح مسودة رد التأمين',

                async primary_action(values) {
                    const amount = flt(values.amount);
                    const reason = (values.reason || '').trim();

                    if (amount <= 0 || !reason) {
                        frappe.throw('أدخل مبلغًا موجبًا وسبب الرد.');
                    }

                    // Refresh the balance before preparing the draft.
                    const latest = await frappe.call({
                        method: 'get_lease_deposit_summary',
                        args: { lease: frm.doc.name }
                    });

                    if (!latest.message) {
                        frappe.throw('تعذر التحقق من الرصيد الحالي.');
                    }

                    const currentAvailable = flt(
                        latest.message.available_refund
                    );

                    if (amount > currentAvailable) {
                        frappe.throw(
                            'المبلغ يتجاوز المتاح حاليًا: ' +
                            currentAvailable
                        );
                    }

                    const result = await frappe.db.get_value(
                        'Account',
                        values.cash_account,
                        [
                            'account_type',
                            'company',
                            'account_currency',
                            'is_group',
                            'disabled'
                        ]
                    );

                    const cash = result.message;

                    if (
                        !cash ||
                        cash.company !== frm.doc.company ||
                        cash.account_currency !== currency ||
                        !['Bank', 'Cash'].includes(cash.account_type) ||
                        cash.is_group ||
                        cash.disabled
                    ) {
                        frappe.throw('اختر حساب بنك أو صندوق صالحًا.');
                    }

                    if (
                        cash.account_type === 'Bank' &&
                        !values.reference_no
                    ) {
                        frappe.throw('أدخل رقم مرجع التحويل البنكي.');
                    }

                    dialog.hide();

                    frappe.new_doc('Journal Entry', {
                        company: frm.doc.company,
                        voucher_type:
                            cash.account_type === 'Bank'
                                ? 'Bank Entry'
                                : 'Cash Entry',
                        custom_residential_lease: frm.doc.name,
                        custom_tenant: frm.doc.party,
                        custom_security_deposit_action: 'Deposit Refund'
                    }, entry => {
                        entry.posting_date = values.posting_date;
                        entry.custom_security_deposit_reason = reason;
                        entry.user_remark =
                            'رد تأمين للعقد ' +
                            frm.doc.name +
                            ' — ' +
                            reason;

                        if (values.reference_no) {
                            entry.cheque_no = values.reference_no;
                            entry.cheque_date = values.posting_date;
                        }

                        entry.accounts = [];

                        const debit = frappe.model.add_child(
                            entry, 'accounts'
                        );
                        debit.account = depositAccount;
                        debit.account_currency = currency;
                        debit.exchange_rate = 1;
                        debit.debit_in_account_currency = amount;
                        debit.credit_in_account_currency = 0;

                        const credit = frappe.model.add_child(
                            entry, 'accounts'
                        );
                        credit.account = values.cash_account;
                        credit.account_currency = currency;
                        credit.exchange_rate = 1;
                        credit.debit_in_account_currency = 0;
                        credit.credit_in_account_currency = amount;
                    });
                }
            });

            dialog.show();
        }, 'التأمين');
    }
});

