async function render_lease_deposit_summary(frm) {
    const field = frm.fields_dict.custom_security_deposit_summary;
    if (!field) return;

    const requestId = (frm.__deposit_summary_request || 0) + 1;
    frm.__deposit_summary_request = requestId;

    const wrapper = field.$wrapper;
    wrapper.empty();

    if (frm.is_new() || frm.is_dirty()) {
        $('<p class="text-muted">')
            .text('احفظ العقد لعرض ملخص التأمين المحدث.')
            .appendTo(wrapper);
        return;
    }

    $('<p class="text-muted">')
        .text('جارٍ حساب ملخص التأمين...')
        .appendTo(wrapper);

    try {
        const response = await frappe.call({
            method: 'get_lease_deposit_summary',
            args: { lease: frm.doc.name }
        });

        if (frm.__deposit_summary_request !== requestId) return;

        if (frm.is_dirty()) {
            wrapper.empty();

            $('<p class="text-muted">')
                .text('احفظ تعديلات العقد ثم حدّث الملخص.')
                .appendTo(wrapper);

            return;
        }

        const data = response.message;
        if (!data) throw new Error('Missing summary');

        wrapper.empty();

        const container = $('<div dir="rtl">')
            .appendTo(wrapper);

        $('<h5>')
            .text('ملخص التأمين')
            .appendTo(container);

        const money = value => new Intl.NumberFormat(
            'ar-SA',
            {
                style: 'currency',
                currency: data.currency
            }
        ).format(flt(value));

        const rows = [
            ['التأمين المطلوب', data.required, ''],
            ['المحصّل المعتمد', data.collected, 'text-success'],
            ['تحصيلات تحت الإعداد', data.drafts, 'text-warning'],
            ['المتبقي للتحصيل', data.remaining, ''],
            [
                'المتاح لإنشاء تحصيل جديد',
                data.available_for_new,
                'text-primary'
            ],
            ['المردود للمستأجر', data.refunded, ''],
            ['المخصوم من التأمين', data.settled, ''],
            [
                'رصيد التأمين المعتمد',
                data.balance,
                'text-success'
            ],
            [
                'ردود وتسويات تحت الإعداد',
                data.draft_outgoing,
                'text-warning'
            ],
            [
                'المتاح للرد أو التسوية',
                data.available_refund,
                'text-primary'
            ]
        ];

        const table = $('<table class="table table-bordered">')
            .appendTo(container);

        const body = $('<tbody>').appendTo(table);

        rows.forEach(([label, value, color]) => {
            if (flt(value) === 0) return;

            const row = $('<tr>').appendTo(body);

            $('<td>')
                .text(label)
                .appendTo(row);

            $('<td>')
                .addClass(color)
                .css('white-space', 'nowrap')
                .text(money(value))
                .appendTo(row);
        });

        if (!body.children().length) {
            table.remove();

            $('<p class="text-muted">')
                .text('لا توجد مبالغ لعرضها في ملخص التأمين.')
                .appendTo(container);
        }

        if (flt(data.excess) > 0) {
            $('<p class="text-danger">')
                .text(
                    'يوجد تجاوز للمطلوب بمبلغ ' +
                    money(data.excess) +
                    '؛ راجع قيود العقد.'
                )
                .appendTo(container);
        }

        if (flt(data.outgoing_excess) > 0) {
            $('<p class="text-danger">')
                .text(
                    'الردود والتسويات تتجاوز الرصيد بمبلغ ' +
                    money(data.outgoing_excess) +
                    '؛ راجع قيود العقد.'
                )
                .appendTo(container);
        }

        $('<small class="text-muted">')
            .text('المسودات تحجز المبلغ ولا تمثل تحصيلًا معتمدًا.')
            .appendTo(container);

        $('<button type="button" class="btn btn-xs btn-default">')
            .text('تحديث الملخص')
            .css('margin', '8px')
            .on('click', () => render_lease_deposit_summary(frm))
            .appendTo(container);

    } catch (error) {
        if (frm.__deposit_summary_request !== requestId) return;

        wrapper.empty();

        $('<p class="text-danger">')
            .text('تعذر تحميل الملخص. راجع رسالة الخطأ والصلاحيات.')
            .appendTo(wrapper);
    }
}

